fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2 - 30);
    }
    let mut x: i32 = host::display::state_get(1);
    if host::display::pointer_down() == 1 {
        if host::display::pointer_x() < w / 2 { x = x - 4; } else { x = x + 4; }
    }
    if x < 0 { x = 0; }
    if x > w - 60 { x = w - 60; }
    host::display::state_set(1, x);
    host::display::clear(0x000000);
    host::display::fill_rect(x, h - 16, 60, 10, 0xffffff);
    host::display::draw_string(8, 8, "HOLD LEFT / RIGHT", 0x808080, 1);
    host::display::present();
}
